    }

    try {
        int count = 1;
        if (descriptor.charAt(0) == '(') {
            // It's a method descriptor
            for (int i = 1; i < descriptor.length(); i++) {
                char c = descriptor.charAt(i);
                if (c == ')') {
                    break;
                } else if (c == 'L' || c == '[') {
                    i++; // Skip the package name or array type declaration
                } else if (c == 'V') {
                    count = 0; // No arguments to pop for void return type
                } else {
                    count++;
                }
            }
        }

        while (count > 0) {
            // Pop from the output frame stack
            stack.pop();
            count--;
        }
    } catch (EmptyStackException e) {
        throw new IllegalStateException("Stack is empty when attempting to pop", e);
    }
}

